package ru.mytv.launcher;
import android.content.Context;
import android.graphics.*;
import android.os.*;
import android.widget.*;
import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class Scenes extends FrameLayout {
 final Handler ui=new Handler(Looper.getMainLooper());final Random random=new Random();final ImageView photo;final TextView clock;final boolean onlyClock;volatile boolean running;boolean showingPhoto;volatile HttpURLConnection connection;ExecutorService pool;int index;
 final String[] urls={"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1920&h=1080&q=80","https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1920&h=1080&q=80","https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1920&h=1080&q=80"};
 public Scenes(Context c,boolean clocks){super(c);onlyClock=clocks;setBackgroundColor(Color.BLACK);photo=new ImageView(c);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);addView(photo,new LayoutParams(-1,-1));clock=new TextView(c);clock.setTextSize(56);clock.setTextColor(0xffcccccc);clock.setText(android.text.format.DateFormat.format("HH:mm",new Date()));addView(clock,new LayoutParams(-2,-2));index=random.nextInt(urls.length);}
 final Runnable time=new Runnable(){public void run(){if(!running)return;clock.setText(android.text.format.DateFormat.format("HH:mm",new Date()));if(!showingPhoto){clock.setVisibility(VISIBLE);clock.setAlpha(1f);}ui.postDelayed(this,1000);}};
 final Runnable move=new Runnable(){public void run(){if(!running)return;if(getWidth()==0||getHeight()==0||clock.getWidth()==0||clock.getHeight()==0){ui.postDelayed(this,100);return;}int pad=Math.round(24*getResources().getDisplayMetrics().density);int maxX=Math.max(0,getWidth()-clock.getWidth()),maxY=Math.max(0,getHeight()-clock.getHeight());int minX=Math.min(pad,maxX),minY=Math.min(pad,maxY);int spanX=Math.max(0,maxX-2*pad),spanY=Math.max(0,maxY-2*pad);clock.animate().cancel();clock.animate().x(minX+random.nextInt(spanX+1)).y(minY+random.nextInt(spanY+1)).setDuration(1200).start();ui.postDelayed(this,15000);}};
 final Runnable next=new Runnable(){public void run(){if(!running)return;load();ui.postDelayed(this,60000);}};
 void start(){if(running)return;running=true;showingPhoto=false;clock.setVisibility(VISIBLE);clock.setAlpha(1f);pool=Executors.newSingleThreadExecutor();ui.post(time);ui.post(move);if(!onlyClock)ui.post(next);}
 void stop(){running=false;ui.removeCallbacksAndMessages(null);HttpURLConnection c=connection;if(c!=null)c.disconnect();if(pool!=null)pool.shutdownNow();photo.animate().cancel();clock.animate().cancel();photo.setImageDrawable(null);}
 void load(){final String url=urls[index++%urls.length];pool.submit(()->{Bitmap result=null;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(url).openConnection();connection=c;c.setConnectTimeout(10000);c.setReadTimeout(10000);if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(!running||total>8388608)throw new IOException("Cancelled or too large");out.write(b,0,n);}}byte[] bytes=out.toByteArray();BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<1||o.outHeight<1)throw new IOException("Invalid image");o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1920||o.outHeight/o.inSampleSize>1080)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;result=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);}catch(Exception e){android.util.Log.w("MyTV","Landscape unavailable",e);}finally{if(c!=null)c.disconnect();connection=null;}final Bitmap bitmap=result;ui.post(()->{if(!running){if(bitmap!=null)bitmap.recycle();return;}photo.animate().cancel();if(bitmap==null){showingPhoto=false;photo.setImageDrawable(null);clock.setAlpha(1f);clock.setVisibility(VISIBLE);}else{photo.setImageBitmap(bitmap);photo.setImageAlpha(255);photo.setAlpha(0f);photo.animate().alpha(1f).setDuration(1200).withEndAction(()->{if(running){showingPhoto=true;clock.setVisibility(INVISIBLE);}}).start();}});});}
}
